init_db()

class LoginRequest(BaseModel):
    username: str
    password: str

class ProductCreate(BaseModel):
    title: str
    category_slug: str
    price: float
    description: Optional[str] = ""
    image_url: Optional[str] = ""
    images: Optional[str] = ""
    badge: Optional[str] = ""

class BannerCreate(BaseModel):
    title: str
    badge: Optional[str] = ""
    subtitle: Optional[str] = ""
    image_url: str

class CategoryCreate(BaseModel):
    name: str
    icon: Optional[str] = "✨"
    theme: Optional[str] = "default"

class SettingsUpdate(BaseModel):
    store_name: Optional[str] = None
    tagline: Optional[str] = None
    whatsapp: Optional[str] = None
    christmas_mode: Optional[str] = None

def verify_token(authorization: Optional[str] = Header(None)):
    if not authorization or authorization != f"Bearer {ADMIN_TOKEN}":
        raise HTTPException(status_code=401, detail="Não autorizado")
    return True

@app.post("/api/login")
def login(creds: LoginRequest):
    if creds.username.strip() == ADMIN_USER and creds.password.strip() == ADMIN_PASS:
        return {"success": True, "token": ADMIN_TOKEN, "username": ADMIN_USER}
    raise HTTPException(status_code=401, detail="Usuário ou senha incorretos")

@app.get("/api/config")
def get_config():
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("SELECT key, value FROM settings")
    settings = {row["key"]: row["value"] for row in cursor.fetchall()}
    conn.close()
    return settings

@app.post("/api/config")
def update_config(data: SettingsUpdate, authorized: bool = Depends(verify_token)):
    conn = get_db()
    cursor = conn.cursor()
    if data.store_name is not None:
        cursor.execute("UPDATE settings SET value = ? WHERE key = 'store_name'", (data.store_name,))
    if data.tagline is not None:
        cursor.execute("UPDATE settings SET value = ? WHERE key = 'tagline'", (data.tagline,))
    if data.whatsapp is not None:
        cursor.execute("UPDATE settings SET value = ? WHERE key = 'whatsapp'", (data.whatsapp,))
    if data.christmas_mode is not None:
        cursor.execute("UPDATE settings SET value = ? WHERE key = 'christmas_mode'", (data.christmas_mode,))
    conn.commit()
    conn.close()
    return {"success": True}

# Banners API
@app.get("/api/banners")
def get_banners():
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("SELECT * FROM banners ORDER BY id DESC")
    rows = cursor.fetchall()
    banners = [dict(r) for r in rows]
    conn.close()
    return banners

@app.post("/api/banners")
def add_banner(b: BannerCreate, authorized: bool = Depends(verify_token)):
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute(
        "INSERT INTO banners (title, badge, subtitle, image_url) VALUES (?, ?, ?, ?)",
        (b.title.strip(), b.badge, b.subtitle, b.image_url)
    )
    conn.commit()
    new_id = cursor.lastrowid
    conn.close()
    return {"success": True, "id": new_id}

@app.delete("/api/banners/{banner_id}")
def delete_banner(banner_id: int, authorized: bool = Depends(verify_token)):
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("DELETE FROM banners WHERE id = ?", (banner_id,))
    conn.commit()
    conn.close()
    return {"success": True}

@app.get("/api/categories")
def get_categories():
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("SELECT * FROM categories ORDER BY id ASC")
    rows = cursor.fetchall()
    categories = [dict(row) for row in rows]
    conn.close()
    return categories

@app.post("/api/categories")
def add_category(cat: CategoryCreate, authorized: bool = Depends(verify_token)):
    slug = cat.name.lower().strip().replace(" ", "-").replace("ã", "a").replace("é", "e").replace("í", "i").replace("ó", "o").replace("ú", "u").replace("ç", "c")
    conn = get_db()
    cursor = conn.cursor()
    try:
        cursor.execute(
            "INSERT INTO categories (name, slug, icon, theme) VALUES (?, ?, ?, ?)",
            (cat.name.strip(), slug, cat.icon or "✨", cat.theme or "default")
        )
        conn.commit()
        cat_id = cursor.lastrowid
    except sqlite3.IntegrityError:
        conn.close()
        raise HTTPException(status_code=400, detail="Esta categoria já existe!")
    conn.close()
    return {"success": True, "id": cat_id, "slug": slug}

@app.delete("/api/categories/{cat_id}")
def delete_category(cat_id: int, authorized: bool = Depends(verify_token)):
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("DELETE FROM categories WHERE id = ?", (cat_id,))
    conn.commit()
    conn.close()
    return {"success": True}

@app.get("/api/products")
def get_products(category: Optional[str] = Query(None)):
    conn = get_db()
    cursor = conn.cursor()
    if category and category != "all":
        cursor.execute("SELECT * FROM products WHERE is_active = 1 AND category_slug = ? ORDER BY id DESC", (category,))
    else:
        cursor.execute("SELECT * FROM products WHERE is_active = 1 ORDER BY id DESC")
    products = [dict(row) for row in cursor.fetchall()]
    conn.close()
    return products

@app.post("/api/products")
def create_product(prod: ProductCreate, authorized: bool = Depends(verify_token)):
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute(
        "INSERT INTO products (title, category_slug, price, description, image_url, images, badge) VALUES (?, ?, ?, ?, ?, ?, ?)",
        (prod.title.strip(), prod.category_slug, prod.price, prod.description, prod.image_url, prod.images, prod.badge)
    )
    conn.commit()
    new_id = cursor.lastrowid
    conn.close()
    return {"success": True, "id": new_id}

@app.put("/api/products/{prod_id}")
def update_product(prod_id: int, prod: ProductCreate, authorized: bool = Depends(verify_token)):
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("""
        UPDATE products 
        SET title = ?, category_slug = ?, price = ?, description = ?, image_url = ?, images = ?, badge = ?
        WHERE id = ?
    """, (prod.title.strip(), prod.category_slug, prod.price, prod.description, prod.image_url, prod.images, prod.badge, prod_id))
    conn.commit()
    conn.close()
    return {"success": True}

@app.delete("/api/products/{prod_id}")
def delete_product(prod_id: int, authorized: bool = Depends(verify_token)):
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("DELETE FROM products WHERE id = ?", (prod_id,))
    conn.commit()
    conn.close()
    return {"success": True}

@app.get("/static/style.css")
def serve_css():
    p = os.path.join(BASE_DIR, "static", "style.css")
    if os.path.exists(p):
        with open(p, "r", encoding="utf-8") as f:
            return Response(content=f.read(), media_type="text/css")
    return Response(content=STYLE_CSS, media_type="text/css")

